// Per-character content box (opaque pixels) within the frame, as fractions of
// the frame size, measured across idle+walk frames. React Native's <Image>
// can't inspect pixels, so the character picker uses these to render every
// character at the same visible body height, feet aligned. Regenerate with
// scripts/measure_content.py if you add/replace a character.
const CONTENT = {
  knight:       { left: 0.125, top: 0.258, w: 0.555, h: 0.617 },
  mage:         { left: 0.156, top: 0.422, w: 0.469, h: 0.453 },
  rogue:        { left: 0.102, top: 0.477, w: 0.461, h: 0.398 },
  pinkMonster:  { left: 0.230, top: 0.172, w: 0.531, h: 0.781 },
  owletMonster: { left: 0.172, top: 0.180, w: 0.660, h: 0.773 },
  dudeMonster:  { left: 0.238, top: 0.176, w: 0.520, h: 0.777 },
};

const resolve = (m) => Image.resolveAssetSource(m).uri;

export const CHARACTER_KEYS = Object.keys(FRAMES);

export const CHARACTER_META = CHARACTER_KEYS.map((k) => ({ key: k, name: FRAMES[k].name }));

// Returns { name, idle:[uri...], walk:[...], run:[...], jump:[...], attack:[...], content }
export function resolveCharacter(key) {
  const c = FRAMES[key] || FRAMES[CHARACTER_KEYS[0]];
  const realKey = FRAMES[key] ? key : CHARACTER_KEYS[0];
  return {
    key: realKey,
    name: c.name,
    idle: c.idle.map(resolve),
    walk: c.walk.map(resolve),
    run: c.run.map(resolve),
    jump: c.jump.map(resolve),
    attack: c.attack.map(resolve),
    content: CONTENT[realKey] || { left: 0, top: 0, w: 1, h: 1 },
  };
}

export function resolveAllCharacters() {
  return CHARACTER_KEYS.map(resolveCharacter);
}
